package org.apache.commons.codec.language;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringEncoder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Metaphone_metaphone_TriageGen0Test {

    private Metaphone metaphone;

    @Before
    public void setUp() {
        metaphone = new Metaphone();
    }

    @Test
    public void testNullOrEmpty() {
        assertEquals("", metaphone.metaphone(null));
        assertEquals("", metaphone.metaphone(""));
    }

    @Test
    public void testSingleCharacter() {
        assertEquals("A", metaphone.metaphone("a"));
        assertEquals("Z", metaphone.metaphone("z"));
    }

    @Test
    public void testInitialExceptions() {
        // KN -> N
        assertEquals("N", metaphone.metaphone("KNIGHT"));
        // K (not KN) -> K
        assertEquals("K", metaphone.metaphone("KITE"));
        // GN (not initial) -> silent G logic via loop
        // AE -> E
        assertEquals("E", metaphone.metaphone("AERIE"));
        // WR -> R
        assertEquals("R", metaphone.metaphone("WRITER"));
        // WH -> W
        assertEquals("W", metaphone.metaphone("WHALE"));
        // X -> S
        assertEquals("S", metaphone.metaphone("Xylophone"));
    }

    @Test
    public void testVowels() {
        // Vowels only at start
        assertEquals("A", metaphone.metaphone("Apple"));
        assertEquals("A", metaphone.metaphone("A"));
        // Vowels in middle should be ignored if not leading
        assertEquals("K", metaphone.metaphone("Kite"));
    }

    @Test
    public void testB() {
        // B is kept
        assertEquals("B", metaphone.metaphone("Bob"));
        // MB at end -> B is silent
        assertEquals("M", metaphone.metaphone("Bomb"));
    }

    @Test
    public void testC() {
        // SCI, SCE, SCY -> discard C
        assertEquals("S", metaphone.metaphone("Scent"));
        // CIA -> X
        assertEquals("X", metaphone.metaphone("CIA"));
        // CI, CE, CY -> S
        assertEquals("S", metaphone.metaphone("City"));
        // SCH -> K
        assertEquals("K", metaphone.metaphone("School"));
        // CH consonant (at start, 3+ len, vowel at index 2)
        assertEquals("K", metaphone.metaphone("CHORD"));
        // CH vowel -> X
        assertEquals("X", metaphone.metaphone("CHAIR"));
        // Normal C -> K
        assertEquals("K", metaphone.metaphone("CAT"));
    }

    @Test
    public void testD() {
        // DGE, DGI, DGY -> J
        assertEquals("J", metaphone.metaphone("DGE"));
        // D -> T
        assertEquals("T", metaphone.metaphone("DOT"));
    }

    @Test
    public void testG() {
        // GH silent at end
        assertEquals("K", metaphone.metaphone("BAGH"));
        // GH silent before consonant
        assertEquals("K", metaphone.metaphone("GHOST"));
        // GN/GNED silent G
        assertEquals("N", metaphone.metaphone("GNAT"));
        assertEquals("N", metaphone.metaphone("GNED"));
        // G + vowel (not hard) -> J
        assertEquals("J", metaphone.metaphone("GENTLE"));
        // G + vowel (hard G) -> K
        assertEquals("K", metaphone.metaphone("GAGGLE"));
    }

    @Test
    public void testH() {
        // Terminal H
        assertEquals("A", metaphone.metaphone("AHA")); // H is terminal here in some contexts, but let's test H at end
        assertEquals("A", metaphone.metaphone("AH"));
        // H after VARSON (V, A, R, S, O, N)
        assertEquals("A", metaphone.metaphone("ASH")); 
        // H + vowel
        assertEquals("H", metaphone.metaphone("HELLO"));
    }

    @Test
    public void testK() {
        // Initial K
        assertEquals("K", metaphone.metaphone("KICK"));
        // K not after C
        assertEquals("K", metaphone.metaphone("KICK"));
        // K after C (should be ignored by K logic)
        assertEquals("S", metaphone.metaphone("BACK"));
    }

    @Test
    public void testP() {
        // PH -> F
        assertEquals("F", metaphone.metaphone("PHONE"));
        // P -> P
        assertEquals("P", metaphone.metaphone("POT"));
    }

    @Test
    public void testQ() {
        // Q -> K
        assertEquals("K", metaphone.metaphone("QUEEN"));
    }

    @Test
    public void testS() {
        // SH, SIO, SIA -> X
        assertEquals("X", metaphone.metaphone("SHE"));
        assertEquals("X", metaphone.metaphone("SION"));
        assertEquals("X", metaphone.metaphone("SIA"));
        // S -> S
        assertEquals("S", metaphone.metaphone("SUN"));
    }

    @Test
    public void testT() {
        // TIA, TIO -> X
        assertEquals("X", metaphone.metaphone("TIARA"));
        assertEquals("X", metaphone.metaphone("TION"));
        // TCH -> silent T
        assertEquals("CH", metaphone.metaphone("WATCH")); // Note: CH logic might apply
        // TH -> 0
        assertEquals("0", metaphone.metaphone("THIN"));
        // T -> T
        assertEquals("T", metaphone.metaphone("TOP"));
    }

    @Test
    public void testV() {
        // V -> F
        assertEquals("F", metaphone.metaphone("VINE"));
    }

    @Test
    public void testWAndY() {
        // W/Y + vowel
        assertEquals("W", metaphone.metaphone("WET"));
        assertEquals("Y", metaphone.metaphone("YES"));
        // W/Y silent if not followed by vowel
        assertEquals("T", metaphone.metaphone("WTR"));
    }

    @Test
    public void testX() {
        // X -> KS
        assertEquals("KS", metaphone.metaphone("XRAY"));
    }

    @Test
    public void testZ() {
        // Z -> S
        assertEquals("S", metaphone.metaphone("ZOO"));
    }

    @Test
    public void testMaxCodeLen() {
        metaphone.setMaxCodeLen(2);
        String res = metaphone.metaphone("METAPHONE");
        assertTrue(res.length() <= 2);
    }
}
